    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DropTargetView {
        return
            try DropTargetView(
                offset: FfiConverterUInt32.read(from: &buf), 
                row: FfiConverterUInt32.read(from: &buf)
        )
    }

