    public static func ==(lhs: RowRange, rhs: RowRange) -> Bool {
        if lhs.first != rhs.first {
            return false
        }
        if lhs.last != rhs.last {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(first)
        hasher.combine(last)
    }
}


